pub struct BatchDriveConfig {
    pub site: &'static str,
    pub stage: InteractiveStage,
    pub fuel_per_step: u64,
    pub step_budget_us: u64,
}

#[derive(Clone)]
pub struct BatchJobParams {
    pub operation: OperationId,
